#!/usr/bin/env node
// Writes go/server/api_routes_gen.go (the RPC route table) and go/server/api_index.go (the API surface) from
// spec/api/routes.json, packages/server/src/api/index.ts (which file builds which group) and the generated request
// and response types of go/apitypes.
//
//   node go/server/testdata/gen-routes.mjs && gofmt -w go/server/api_routes_gen.go go/server/api_index.go
//
// The route manifest test (routes_test.go) fails when the table and routes.json disagree.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, '..', '..', '..');
const routes = JSON.parse(readFileSync(join(repo, 'spec/api/routes.json'), 'utf8'));

const initialisms = { Id: 'ID', Ids: 'IDs', Url: 'URL', Urls: 'URLs', Api: 'API', Json: 'JSON', Ip: 'IP', Uri: 'URI', Ips: 'IPs' };
const pascal = (name) =>
  (name[0].toUpperCase() + name.slice(1)).replace(/(Ids|Id|Urls|Url|Api|Json|Ips|Ip|Uri)(?=[A-Z0-9]|$)/g, (m) => initialisms[m] ?? m);

// Group -> source module, in api/index.ts order (the order of the API struct).
const indexSource = readFileSync(join(repo, 'packages/server/src/api/index.ts'), 'utf8');
const imports = {};
for (const m of indexSource.matchAll(/import \{([^}]*)\} from '(\.\.?\/[^']+)'/g))
  for (const name of m[1].split(',')) imports[name.trim().replace(/^type /, '')] = m[2];
const groups = [{ group: 'auth', factory: 'createAuthApi', module: 'http.ts' }];
for (const m of indexSource.matchAll(/^\s+(\w+): (create\w+)\(ctx\)/gm))
  groups.push({ group: m[1], factory: m[2], module: join('api', imports[m[2]]).replace(/\\/g, '/').replace(/^api\/\.\.\//, '').replace(/\.js$/, '.ts') });

// Route -> generated Input/Output types.
const opsSource = readFileSync(join(repo, 'go/apitypes/operations_gen.go'), 'utf8');
const table = opsSource.slice(opsSource.indexOf('var operationTable'));
const rows = [...table.matchAll(/Path:\s*"([^"]+)"/g)].map((m) => m[1]);
const types = {};
for (const m of opsSource.matchAll(/\tOp\w+ = Op\[([\w.*]+), ([\w.*[\]]+)\]\{&operationTable\[(\d+)\]\}/g))
  types[rows[Number(m[3])]] = { input: m[1], output: m[2] };

const lines = [];
const credentialType = 'core.CredentialInput';
for (const row of routes.rpc) {
  if (row.call === 'beginMfa' || row.call === 'confirmMfa') continue; // http.go dispatchAuth builds their inputs
  const type = types[row.path];
  if (!type) throw new Error(`no generated types for ${row.path}`);
  const field = pascal(row.group);
  const method = pascal(row.method);
  let call;
  if (row.group === 'assertions')
    call = `\t\tresult, err := api.${field}.${method}(ctx, credential, body)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\treturn result, nil`;
  else {
    const args = row.call === 'input' ? `ctx, Input[apitypes.${type.input}](body)` : `ctx, credential, Input[apitypes.${type.input}](body)`;
    call = `\t\tout, err := api.${field}.${method}(${args})\n\t\treturn out.Value, err`;
  }
  lines.push(`\t"${row.path}": func(ctx context.Context, api *API, credential ${credentialType}, body *core.Object) (any, error) {\n${call}\n\t},`);
}

const header = `// Code generated by go/server/testdata/gen-routes.mjs from spec/api/routes.json; DO NOT EDIT.\n\npackage server\n\n`;
writeFileSync(
  join(repo, 'go/server/api_routes_gen.go'),
  `${header}import (\n\t"context"\n\n\t"github.com/Better-IAM/better-iam/go/apitypes"\n\t"github.com/Better-IAM/better-iam/go/core"\n)\n\n` +
    `// rpcCall calls the API method of one RPC route: public methods with the body, the others with the request\n// credential and the body (http.go dispatch).\ntype rpcCall func(ctx context.Context, api *API, credential core.CredentialInput, body *core.Object) (any, error)\n\n` +
    `// rpcRoutes holds every RPC route of spec/api/routes.json except auth/beginMfa and auth/confirmMfa, whose inputs\n// http.go builds itself (dispatchAuth).\nvar rpcRoutes = map[string]rpcCall{\n${lines.join('\n')}\n}\n`,
);

const fields = groups.map(({ group, module }) => `\t// ${pascal(group)} is the \`${group}\` group (${module}).\n\t${pascal(group)} *${pascal(group)}API`);
const ctors = groups
  .filter(({ group }) => group !== 'auth')
  .map(({ group, factory }) => `\t\t${pascal(group)}: ${pascal(factory).replace(/Api$/, 'API')}(server),`);
writeFileSync(
  join(repo, 'go/server/api_index.go'),
  `// Code generated by go/server/testdata/gen-routes.mjs from packages/server/src/api/index.ts; DO NOT EDIT.\n\npackage server\n\n` +
    `// Port of packages/server/src/api/index.ts: the provisioning API. Every group is a struct of (credential, input)\n// operations that run through the transactional authorization envelope; the HTTP router maps\n// POST {basePath}/{group}/{method} onto them (api_routes_gen.go).\n\n` +
    `// API is the provisioning API (createApi): one field per group, in api/index.ts order.\ntype API struct {\n${fields.join('\n')}\n}\n\n` +
    `// CreateAPI builds every group over the context; auth is the authentication group (http.go CreateAuthAPI).\nfunc CreateAPI(server *ServerContext, auth *AuthAPI) *API {\n\treturn &API{\n\t\tAuth: auth,\n${ctors.join('\n')}\n\t}\n}\n`,
);
try {
  execFileSync('gofmt', ['-w', join(repo, 'go/server/api_routes_gen.go'), join(repo, 'go/server/api_index.go')]);
} catch {
  console.error('gofmt not found: run gofmt -w on the generated files');
}
console.log(`api_routes_gen.go: ${lines.length} routes; api_index.go: ${groups.length} groups`);
